def binary_search(arr, x):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        m = (lo + hi) // 2
        if arr[m] == x:
            return m
        if arr[m] < x:
            lo = m + 1
        else:
            hi = m - 1
    return -1
```

